#pragma once

inline void configure_exact_host_kv_pinned_chunks(){_putenv_s("NINFER_EXL3_OSCAR_L0_ONLY","0");_putenv_s("NINFER_EXL3_EXACT_HOST_KV","1");_putenv_s("NINFER_EXL3_EXACT_HOST_KV_BATCH_SYNC","1");_putenv_s("NINFER_EXL3_EXACT_HOST_KV_BATCH_COPY","1");}
inline void unset_exact_host_kv_pinned_chunks(){_putenv_s("NINFER_EXL3_EXACT_HOST_KV_PINNED_CHUNKS","");}

void run_exact_host_kv_pinned_chunks_screen(Exl3TextModel& target,const std::vector<std::int64_t>& code,const std::vector<std::int64_t>& prose,bool candidate_default=false){using Request=ninfer::exl3::Exl3VeriCacheRequest;const int prefix=target.max_context()>=4352?4096:96;require(code.size()>=prefix&&prose.size()>=prefix,"host KV pinned-chunk fixture/context extent");configure_exact_host_kv_pinned_chunks();_putenv_s("NINFER_EXL3_EXACT_HOST_KV_PINNED_CHUNKS","0");auto control=target.create_context(true);control->prepare_continuation(8);if(candidate_default)unset_exact_host_kv_pinned_chunks();else _putenv_s("NINFER_EXL3_EXACT_HOST_KV_PINNED_CHUNKS","1");auto candidate=target.create_context(true);candidate->prepare_continuation(8);const auto greedy=[](Exl3TextContext& context){const auto logits=context.logits_host();require(!logits.empty()&&std::none_of(logits.begin(),logits.end(),[](float value){return !std::isfinite(value);}),"host KV pinned-chunk finite logits");return static_cast<std::int64_t>(std::max_element(logits.begin(),logits.end())-logits.begin());};for(const auto& fixture:std::array<std::pair<const char*,const std::vector<std::int64_t>*>,2>{std::pair{"code",&code},std::pair{"prose",&prose}}){const std::vector<std::int64_t> input(fixture.second->begin(),fixture.second->begin()+prefix);const auto run=[&](Exl3TextContext& context){const auto before=context.host_kv_stats();const auto started=std::chrono::steady_clock::now();const auto request=Request::initialize(context,input,1024);const double prefill_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-started).count();std::vector<std::int64_t> tokens;for(int row=0;row<8;++row){const auto token=greedy(context);tokens.push_back(token);context.decode(token);}const auto after=context.host_kv_stats();auto delta=after;delta.h2d_bytes-=before.h2d_bytes;delta.d2h_bytes-=before.d2h_bytes;delta.transfer_calls-=before.transfer_calls;delta.copy_submissions-=before.copy_submissions;delta.completed_rows-=before.completed_rows;return std::tuple{prefill_ms,tokens,context.export_exact_host_state(),delta};};const auto baseline=run(*control),changed=run(*candidate);require(std::get<1>(baseline)==std::get<1>(changed)&&std::get<2>(baseline)->same_payload(*std::get<2>(changed)),"host KV pinned-chunk token/state");const auto a=std::get<3>(baseline),b=std::get<3>(changed);require(a.h2d_bytes==b.h2d_bytes&&a.d2h_bytes==b.d2h_bytes&&a.transfer_calls==b.transfer_calls&&a.completed_rows==b.completed_rows&&a.pinned_staging_bytes==0&&b.pinned_staging_bytes==2*(1U<<20),"host KV pinned-chunk accounting");std::cout<<"EXACT_HOST_KV_PINNED_CHUNKS fixture="<<fixture.first<<" prefix="<<prefix<<" decode_rows=8 control_prefill_ms="<<std::get<0>(baseline)<<" candidate_prefill_ms="<<std::get<0>(changed)<<" control_submissions="<<a.copy_submissions<<" candidate_submissions="<<b.copy_submissions<<" pinned_bytes="<<b.pinned_staging_bytes<<std::endl;}std::cout<<"EXACT_HOST_KV_PINNED_CHUNKS PASS fixtures=2 prefix="<<prefix<<" decode_rows=8 exact_tokens_state=1 logical_accounting=1 bounded_pinned_bytes="<<2*(1U<<20)<<" default_candidate="<<(candidate_default?1:0)<<std::endl;}

void run_exact_host_kv_pinned_chunks_t3(Exl3TextModel& target,const std::vector<std::int64_t>& code,const std::vector<std::int64_t>& prose,const std::vector<std::int64_t>& structured,const std::vector<std::int64_t>& heldout){using Request=ninfer::exl3::Exl3VeriCacheRequest;constexpr int prefix=4096;require(target.max_context()==4352,"host KV pinned-chunk T3 context extent");configure_exact_host_kv_pinned_chunks();const auto greedy=[](Exl3TextContext& context){const auto logits=context.logits_host();require(!logits.empty()&&std::none_of(logits.begin(),logits.end(),[](float value){return !std::isfinite(value);}),"host KV pinned-chunk T3 finite logits");return static_cast<std::int64_t>(std::max_element(logits.begin(),logits.end())-logits.begin());};const auto median=[](std::vector<double> values){std::sort(values.begin(),values.end());return values[values.size()/2];};const std::array<std::pair<const char*,const std::vector<std::int64_t>*>,4> fixtures={std::pair{"code",&code},std::pair{"prose",&prose},std::pair{"structured",&structured},std::pair{"heldout_mixed",&heldout}};for(const auto& fixture:fixtures){require(fixture.second->size()>=prefix,"host KV pinned-chunk T3 fixture extent");const std::vector<std::int64_t> input(fixture.second->begin(),fixture.second->begin()+prefix);_putenv_s("NINFER_EXL3_EXACT_HOST_KV_PINNED_CHUNKS","0");auto control=target.create_context(true);control->prepare_continuation(8);_putenv_s("NINFER_EXL3_EXACT_HOST_KV_PINNED_CHUNKS","1");auto candidate=target.create_context(true);candidate->prepare_continuation(8);struct Result{double prefill_ms=0;std::vector<std::int64_t> tokens;std::shared_ptr<const ninfer::exl3::Exl3ExactHostState> state;ninfer::exl3::Exl3HostKVStats delta;};const auto run=[&](Exl3TextContext& context){const auto before=context.host_kv_stats();const auto started=std::chrono::steady_clock::now();const auto request=Request::initialize(context,input,1024);const double prefill_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-started).count();std::vector<std::int64_t> tokens;for(int row=0;row<8;++row){const auto token=greedy(context);tokens.push_back(token);context.decode(token);}const auto after=context.host_kv_stats();auto delta=after;delta.h2d_bytes-=before.h2d_bytes;delta.d2h_bytes-=before.d2h_bytes;delta.transfer_calls-=before.transfer_calls;delta.copy_submissions-=before.copy_submissions;delta.completed_rows-=before.completed_rows;return Result{prefill_ms,std::move(tokens),context.export_exact_host_state(),delta};};std::vector<double> control_ms,candidate_ms;for(int rep=0;rep<3;++rep){const std::array<bool,2> order=rep==1?std::array{true,false}:std::array{false,true};Result first,second;for(int ordinal=0;ordinal<2;++ordinal){const bool changed=order[ordinal];const auto result=run(changed?*candidate:*control);(changed?candidate_ms:control_ms).push_back(result.prefill_ms);if(ordinal==0)first=result;else second=result;std::cout<<"EXACT_HOST_KV_PINNED_CHUNKS_CASE fixture="<<fixture.first<<" rep="<<rep<<" order="<<ordinal<<" arm="<<(changed?"pinned_chunks":"batch_pages")<<" prefill_ms="<<result.prefill_ms<<" tps="<<prefix*1000/result.prefill_ms<<" submissions="<<result.delta.copy_submissions<<std::endl;}require(first.tokens==second.tokens&&first.state->same_payload(*second.state),"host KV pinned-chunk T3 token/state");require(first.delta.h2d_bytes==second.delta.h2d_bytes&&first.delta.d2h_bytes==second.delta.d2h_bytes&&first.delta.transfer_calls==second.delta.transfer_calls&&first.delta.completed_rows==second.delta.completed_rows,"host KV pinned-chunk T3 logical accounting");}const double baseline=median(control_ms),changed=median(candidate_ms);std::cout<<"EXACT_HOST_KV_PINNED_CHUNKS_T3 fixture="<<fixture.first<<" batch_median_ms="<<baseline<<" pinned_median_ms="<<changed<<" wall_reduction_percent="<<(baseline-changed)*100/baseline<<" pinned_tps="<<prefix*1000/changed<<std::endl;}std::cout<<"EXACT_HOST_KV_PINNED_CHUNKS_T3 PASS fixtures=4 pairs=3 prefix=4096 decode_rows=8 exact_tokens_state=1 logical_accounting=1 bounded_pinned_bytes="<<2*(1U<<20)<<std::endl;}
